export async function POST() {
  try {
    const invoiceLink = await botApi.createInvoiceLink(
      "Title", // Title of the item
      "Some description", // Description of the item
      "{}", // Payload
      "", // Empty for Telegram Stars payment
      "XTR", // Currency (Telegram Stars)
